import urllib.request, json
import os
def load_bot_token():
    tg_cfg_path = os.path.expanduser('~/.openclaw/workspace-orchestrator/config/telegram_card_config.json')
    try:
        with open(tg_cfg_path) as f: tg_cfg = json.load(f)
    except Exception: tg_cfg = {}
    token = str(tg_cfg.get('bot_token') or '').strip()
    if token: return token

    try:
        with open(os.path.expanduser('~/.openclaw/openclaw.json')) as f: data = json.load(f)
        telegram = (data.get('channels') or {}).get('telegram') or {}
        accts = telegram.get('accounts') or []
        for acct in accts:
            if tg_cfg.get('telegram_account') == acct.get('id'):
                return acct.get('token')
        return telegram.get('token') or ''
    except Exception as e: return str(e)

token = load_bot_token()
